<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { ApiError } from "@/services/http";
import { createAsignacion, getAccessOptions, getAssignmentOptions, listTarjetasDisponibles, listValidRequests, type PerfilAcceso, type SolicitudAsignable, type TarjetaDisponible } from "@/services/tarjetas";
import type { Beneficiary } from "@/services/beneficiarios";

const props = defineProps<{ beneficiary: Beneficiary; canCreateRequest: boolean; initialRequest?: SolicitudAsignable | null }>();
const emit = defineEmits<{ (event: "close"): void; (event: "assigned"): void; (event: "create-request"): void }>();
const loading = ref(true); const saving = ref(false); const error = ref("");
const requests = ref<SolicitudAsignable[]>([]); const cards = ref<TarjetaDisponible[]>([]); const profiles = ref<PerfilAcceso[]>([]);
const options = ref<{ tiposVigencia: Array<{ idTipoValor: number; nombreTipoValor: string }>; estadosAsignacion: Array<{ idTipoValor: number; nombreTipoValor: string }> }>({ tiposVigencia: [], estadosAsignacion: [] });
const selectedRequest = ref<SolicitudAsignable | null>(null); const selectedCard = ref<TarjetaDisponible | null>(null);
const search = ref(""); const page = ref(1); const pageSize = 8;
const form = ref({ idTipoVigencia: 0, idEstadoAsignacion: 0, idPerfilAcceso: "", fechaInicioVigencia: "", fechaFinVigencia: "" });
const message = (cause: unknown) => cause instanceof ApiError ? cause.message : "No fue posible completar la asignación. Intente nuevamente.";
const beneficiaryName = computed(() => [props.beneficiary.primerNombre, props.beneficiary.segundoNombre, props.beneficiary.primerApellido, props.beneficiary.segundoApellido].filter(Boolean).join(" "));
const beneficiaryCode = computed(() => props.beneficiary.codigoCarne ?? props.beneficiary.numeroCuenta ?? "Sin código o cuenta");
const filteredCards = computed(() => { const term = search.value.trim().toLowerCase(); return cards.value.filter(card => !term || [card.codigoTarjeta, card.codigoExterno, card.numeroSerie].some(value => value?.toLowerCase().includes(term))); });
const pageCount = computed(() => Math.max(1, Math.ceil(filteredCards.value.length / pageSize)));
const visibleCards = computed(() => filteredCards.value.slice((page.value - 1) * pageSize, page.value * pageSize));
const valid = computed(() => Boolean(selectedRequest.value && selectedCard.value && form.value.idTipoVigencia && form.value.idEstadoAsignacion && form.value.fechaInicioVigencia && (!form.value.fechaFinVigencia || form.value.fechaFinVigencia >= form.value.fechaInicioVigencia)));
function formatDate(value: string | null) { return value ? value.slice(0, 10).split("-").reverse().join("/") : "Sin fecha"; }
function selectRequest(request: SolicitudAsignable) { selectedRequest.value = request; form.value.idTipoVigencia = request.idTipoVigencia; form.value.fechaInicioVigencia = request.fechaInicioSolicitada?.slice(0, 10) ?? ""; form.value.fechaFinVigencia = request.fechaFinSolicitada?.slice(0, 10) ?? ""; error.value = ""; }
function selectCard(card: TarjetaDisponible) { selectedCard.value = card; error.value = ""; }
function changeSearch() { page.value = 1; /* conservar la selección si sigue siendo elegible */ }
async function load() {
  loading.value = true; error.value = "";
   try { const previousCard = selectedCard.value?.idTarjeta; const [requestItems, available, assignmentOptions, accessOptions] = await Promise.all([listValidRequests(props.beneficiary.idBeneficiario), listTarjetasDisponibles(), getAssignmentOptions(), getAccessOptions()]); requests.value = requestItems; cards.value = available; options.value = assignmentOptions; profiles.value = accessOptions.perfilesAcceso; if (previousCard) selectedCard.value = available.find(card => String(card.idTarjeta) === String(previousCard)) ?? null; const initial = props.initialRequest ? requestItems.find(item => String(item.idSolicitud) === String(props.initialRequest?.idSolicitud)) : requestItems[0]; if (props.initialRequest && !initial) error.value = "La solicitud seleccionada ya no está aprobada o no es elegible para asignación."; else if (initial && !initial.idAsignacionVigente) selectRequest(initial); else if (props.initialRequest?.idAsignacionVigente) error.value = "La solicitud ya tiene una tarjeta asignada."; }
  catch (cause) { error.value = message(cause); } finally { loading.value = false; }
}
async function assign() {
  if (!valid.value || saving.value || !selectedRequest.value || !selectedCard.value) return; saving.value = true; error.value = "";
  try { await createAsignacion({ idTarjeta: selectedCard.value.idTarjeta, idBeneficiario: props.beneficiary.idBeneficiario, idSolicitud: selectedRequest.value.idSolicitud, idTipoVigencia: form.value.idTipoVigencia, idEstadoAsignacion: form.value.idEstadoAsignacion, fechaInicioVigencia: new Date(`${form.value.fechaInicioVigencia}T00:00:00`).toISOString(), fechaFinVigencia: form.value.fechaFinVigencia ? new Date(`${form.value.fechaFinVigencia}T00:00:00`).toISOString() : null, idPerfilAcceso: form.value.idPerfilAcceso ? Number(form.value.idPerfilAcceso) : null }); emit("assigned"); }
  catch (cause) { error.value = message(cause); } finally { saving.value = false; }
}
onMounted(() => { void load(); });
</script>

<template>
  <div class="bo-modal-backdrop" @click.self="!saving && emit('close')">
    <section class="bo-modal assignment-modal" role="dialog" aria-modal="true" aria-labelledby="assignment-title">
      <header class="assignment-header"><div><span class="bo-eyebrow">Expediente del beneficiario</span><h2 id="assignment-title">Asignar tarjeta</h2><p>Seleccione una solicitud aprobada y una tarjeta disponible para registrar la asignación.</p></div><button class="bo-close" type="button" :disabled="saving" aria-label="Cerrar" @click="emit('close')">×</button></header>
      <div class="assignment-identity"><div class="identity-person"><span class="identity-label">Beneficiario</span><strong>{{ beneficiaryName }}</strong></div><div><span class="identity-label">Código / cuenta</span><strong>{{ beneficiaryCode }}</strong></div><div><span class="identity-label">Tipo</span><strong>{{ beneficiary.nombreTipoBeneficiario ?? "No disponible" }}</strong></div><div><span class="identity-label">Carrera</span><strong>{{ beneficiary.nombreCarrera ?? "No disponible" }}</strong></div></div>
      <div v-if="loading" class="bo-state">Cargando solicitudes, tarjetas y perfiles...</div>
      <template v-else>
        <p v-if="error" class="bo-form-error assignment-error" role="alert">{{ error }}</p>
        <section class="assignment-section"><h3><span>1</span><b>Solicitud autorizada</b></h3><p class="section-help">{{ initialRequest ? "Solicitud seleccionada desde el expediente." : "Seleccione la solicitud aprobada que habilita la asignación de la tarjeta." }}</p><div v-if="!requests.length" class="bo-state assignment-empty"><strong>No existen solicitudes aprobadas elegibles para asignación.</strong><button v-if="canCreateRequest" class="bo-btn" type="button" @click="emit('create-request')">Crear solicitud desde el expediente</button></div><div v-else-if="initialRequest" class="assignment-option selected assignment-locked"><span><strong>{{ selectedRequest?.codigoSolicitud ?? initialRequest.codigoSolicitud }}</strong><small><em>{{ selectedRequest?.nombreEstadoSolicitud ?? initialRequest.nombreEstadoSolicitud }}</em>{{ selectedRequest?.nombreTipoSolicitud ?? initialRequest.nombreTipoSolicitud ?? "Solicitud" }} · {{ selectedRequest?.nombrePeriodoAcademico ?? initialRequest.nombrePeriodoAcademico ?? "Sin período" }}</small><small>{{ selectedRequest?.nombreTipoVigencia ?? initialRequest.nombreTipoVigencia }} · {{ formatDate(selectedRequest?.fechaInicioSolicitada ?? initialRequest.fechaInicioSolicitada) }} — {{ formatDate(selectedRequest?.fechaFinSolicitada ?? initialRequest.fechaFinSolicitada) }}</small></span></div><div v-else class="assignment-options"><label v-for="request in requests" :key="request.idSolicitud" class="assignment-option" :class="{ selected: selectedRequest?.idSolicitud === request.idSolicitud }"><input type="radio" name="assignment-request" :checked="selectedRequest?.idSolicitud === request.idSolicitud" @change="selectRequest(request)" /><span><strong>{{ request.codigoSolicitud }}</strong><small><em>{{ request.nombreEstadoSolicitud }}</em>{{ request.nombreTipoVigencia }} · {{ formatDate(request.fechaInicioSolicitada) }} — {{ formatDate(request.fechaFinSolicitada) }}</small></span></label></div></section>
        <section class="assignment-section"><h3><span>2</span><b>Tarjeta disponible</b></h3><p class="section-help">Seleccione una tarjeta activa sin asignación vigente.</p><label class="assignment-search-label">Buscar tarjeta<input v-model="search" class="assignment-search" placeholder="Código, serie o código externo" aria-label="Buscar tarjeta disponible" @input="changeSearch" /></label><div v-if="!visibleCards.length" class="bo-state assignment-empty">No hay tarjetas disponibles para la búsqueda.</div><div v-else class="bo-table-wrap assignment-table"><table><thead><tr><th class="radio-column"></th><th>Código</th><th>Serie</th><th>Estado</th></tr></thead><tbody><tr v-for="card in visibleCards" :key="card.idTarjeta" :class="{ 'row-selected': selectedCard?.idTarjeta === card.idTarjeta }"><td><input type="radio" name="assignment-card" :checked="selectedCard?.idTarjeta === card.idTarjeta" :aria-label="`Seleccionar ${card.codigoTarjeta}`" @change="selectCard(card)" /></td><td><strong>{{ card.codigoTarjeta }}</strong><small v-if="card.codigoExterno">Externo: {{ card.codigoExterno }}</small></td><td>{{ card.numeroSerie ?? "—" }}</td><td><span class="availability-badge">Disponible</span></td></tr></tbody></table><footer class="bo-pagination"><span>Página {{ page }} de {{ pageCount }}</span><div><button class="bo-page-button" type="button" :disabled="page <= 1" @click="page--">Anterior</button><button class="bo-page-button" type="button" :disabled="page >= pageCount" @click="page++">Siguiente</button></div></footer></div></section>
        <section class="assignment-section"><h3><span>3</span><b>Detalles de la asignación</b></h3><p class="section-help">Defina el perfil de acceso y el período de vigencia de la tarjeta.</p><div class="bo-form-grid assignment-form"><label>Perfil de acceso<select v-model="form.idPerfilAcceso"><option value="">Sin perfil</option><option v-for="profile in profiles" :key="profile.idPerfilAcceso" :value="String(profile.idPerfilAcceso)">{{ profile.codigoPerfilAcceso }} · {{ profile.nombrePerfilAcceso }}</option></select><small class="field-help">Define los niveles de acceso permitidos con la tarjeta.</small></label><label>Tipo de vigencia *<select v-model.number="form.idTipoVigencia" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.tiposVigencia" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select><small class="field-help">Determina cómo se establece el período de vigencia de la tarjeta.</small></label><label>Estado de asignación *<select v-model.number="form.idEstadoAsignacion" required><option :value="0" disabled>Seleccione...</option><option v-for="item in options.estadosAsignacion" :key="item.idTipoValor" :value="item.idTipoValor">{{ item.nombreTipoValor }}</option></select><small class="field-help">Estado inicial de la asignación de la tarjeta.</small></label><label>Fecha de inicio de vigencia *<input v-model="form.fechaInicioVigencia" type="date" required /><small class="field-help">Fecha desde la cual comienza la vigencia de la tarjeta.</small></label><label>Fecha de fin de vigencia<input v-model="form.fechaFinVigencia" type="date" :min="form.fechaInicioVigencia" /><small class="field-help">Puede extenderse más allá del período de la solicitud aprobada.</small></label></div></section>
      </template>
      <footer class="form-actions"><button type="button" class="bo-btn" :disabled="saving" @click="emit('close')">Cancelar</button><button type="button" class="bo-btn bo-btn-primary" :disabled="saving || !valid" @click="assign">{{ saving ? "Guardando asignación..." : "Confirmar asignación" }}</button></footer>
    </section>
  </div>
</template>

<style scoped>
.assignment-modal{width:min(900px,calc(100vw - 32px));padding:26px}.assignment-header{margin-bottom:20px!important}.assignment-header p{margin:7px 0 0;color:var(--bo-muted);font-size:12px;line-height:1.5}.assignment-identity{display:grid;grid-template-columns:1.7fr 1fr 1fr 1.2fr;gap:1px;margin-bottom:22px;border:1px solid var(--bo-line);border-radius:9px;overflow:hidden;background:var(--bo-line)}.assignment-identity>div{display:grid;align-content:center;gap:6px;min-width:0;padding:13px 14px;background:#f8fafb}.assignment-identity strong{color:var(--bo-dark);font-size:12px;overflow-wrap:anywhere}.identity-label{color:var(--bo-muted);font-size:10px;font-weight:800;letter-spacing:.05em;text-transform:uppercase}.assignment-section{margin-top:22px;padding-top:19px;border-top:1px solid #e7edef}.assignment-section h3{display:flex;align-items:center;gap:9px;margin:0;color:var(--bo-dark);font-size:14px}.assignment-section h3>span{display:grid;width:25px;height:25px;place-items:center;border-radius:50%;color:#fff;background:var(--bo-blue);font-size:12px}.assignment-section h3 b{font-weight:800}.section-help{margin:7px 0 12px 34px;color:var(--bo-muted);font-size:11px}.assignment-options{display:grid;gap:8px}.assignment-option{display:flex!important;grid-template-columns:none!important;flex-direction:row;align-items:flex-start;gap:10px;padding:12px 13px;border:1px solid var(--bo-line);border-radius:8px;cursor:pointer}.assignment-option.selected,.assignment-option:hover{border-color:#8db8cb;background:#f5fafc}.assignment-option input{width:auto!important;margin-top:2px}.assignment-option span{display:grid;gap:5px}.assignment-option small{color:var(--bo-muted);font-weight:400}.assignment-option small em{margin-right:8px;padding:3px 7px;border-radius:999px;color:#26784b;background:#e7f5ec;font-size:10px;font-style:normal;font-weight:700}.assignment-empty{min-height:74px;padding:14px;border:1px dashed var(--bo-line);border-radius:7px}.assignment-empty .bo-btn{margin-top:4px}.assignment-search-label{display:grid;gap:6px;color:var(--bo-dark);font-size:11px;font-weight:700}.assignment-search{width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--bo-line);border-radius:7px;color:var(--bo-text);font-size:12px}.assignment-search:focus{outline:2px solid rgb(0 90 135 / 16%);border-color:var(--bo-blue)}.assignment-table{margin-top:10px;border:1px solid var(--bo-line);border-radius:8px}.assignment-table table{min-width:0}.assignment-table td,.assignment-table th{white-space:normal}.assignment-table td small{display:block;margin-top:3px;color:var(--bo-muted);font-size:10px}.assignment-table tr.row-selected td{background:#f5fafc}.radio-column{width:38px}.availability-badge{display:inline-flex;align-items:center;gap:5px;padding:4px 8px;border-radius:999px;color:#26784b;background:#e7f5ec;font-size:10px;font-weight:700}.availability-badge::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.assignment-form{margin-left:34px}.assignment-form select{width:100%;box-sizing:border-box;padding:9px 10px;border:1px solid var(--bo-line);border-radius:6px;color:var(--bo-text);background:#fff;font-size:12px}.field-help{color:var(--bo-muted);font-size:10px;font-weight:400}.assignment-error{margin:12px 0 0;padding:10px 12px;border:1px solid #e4bebe;border-radius:7px;background:#fff1f1}.form-actions{margin-top:24px;padding-top:17px;border-top:1px solid #e7edef}@media(max-width:700px){.assignment-modal{width:calc(100vw - 20px);padding:18px}.assignment-identity{grid-template-columns:1fr 1fr}.identity-person{grid-column:1/-1}.assignment-form{margin-left:0}}@media(max-width:450px){.assignment-identity{grid-template-columns:1fr}.identity-person{grid-column:auto}}
.assignment-form label{display:grid;grid-template-rows:auto 38px auto;align-content:start;gap:6px;min-width:0;color:var(--bo-dark);font-size:11px;font-weight:700;line-height:1.35}.assignment-form select,.assignment-form input{width:100%;height:38px;box-sizing:border-box;padding:0 10px;border:1px solid var(--bo-line);border-radius:6px;color:var(--bo-text);background:#fff;font:inherit;font-size:12px}.assignment-form select:focus,.assignment-form input:focus{outline:2px solid rgb(0 90 135 / 16%);border-color:var(--bo-blue)}.field-help{min-height:27px;color:var(--bo-muted);font-size:10px;font-weight:400;line-height:1.35}
</style>
